"use client";

import * as React from "react";
import { cn } from "@/lib/buildora/utils";
import { useReducedMotion } from "@/hooks/buildora/use-reduced-motion";

export type InfiniteMarqueeProps = React.HTMLAttributes<HTMLDivElement> & {
  direction?: "left" | "right";
  speed?: "slow" | "normal" | "fast";
  pauseOnHover?: boolean;
  gap?: number;
};

export function InfiniteMarquee({
  direction = "left",
  speed = "normal",
  pauseOnHover = true,
  gap = 48,
  className,
  children,
  ...rest
}: InfiniteMarqueeProps) {
  const reduced = useReducedMotion();

  const speedValues = {
    slow: 50,
    normal: 30,
    fast: 15,
  };

  const duration = speedValues[speed];
  const items = React.Children.toArray(children);

  if (items.length === 0) return null;

  const renderItems = (ariaHidden: boolean) => (
    <div
      aria-hidden={ariaHidden || undefined}
      className="flex shrink-0 items-center"
      style={{ gap: `${gap}px`, paddingRight: `${gap}px` }}
    >
      {items.map((child, i) => (
        <React.Fragment key={i}>{child}</React.Fragment>
      ))}
    </div>
  );

  // Static fallbacks: no animation, no duplication.
  if (reduced) {
    return (
      <div className={cn("relative overflow-hidden", className)} {...rest}>
        <div className="flex flex-wrap items-center" style={{ gap: `${gap}px` }}>
          {items.map((child, i) => (
            <React.Fragment key={i}>{child}</React.Fragment>
          ))}
        </div>
      </div>
    );
  }

  return (
    <div
      className={cn(
        "group relative overflow-hidden",
        "[mask-image:linear-gradient(to_right,transparent,black_8%,black_92%,transparent)]",
        className
      )}
      {...rest}
    >
      <div
        className={cn(
          "flex w-max",
          pauseOnHover && "group-hover:[animation-play-state:paused]"
        )}
        style={{
          animation: `buildora-marquee ${duration}s linear infinite`,
          animationDirection: direction === "right" ? "reverse" : "normal",
        }}
      >
        {renderItems(false)}
        {renderItems(true)}
      </div>
    </div>
  );
}

export default InfiniteMarquee;
